/**
 * Java client emitter for OpenAPI SDK generator.
 * Emits buildable Java 17+ client artifacts:
 *   - Operations.java: Typed registry of all OpenAPI operations
 *   - models/Models.java: Typed DTOs/records for all schema definitions
 */
import type { JsonSchema, OpenApiDocument, NormalizedOperation, NormalizedParam } from '../../src/lib/openapi/normalize';
import type { Emitter } from './emitters';
import { modelName } from './emit-typescript';

const HEADER = `// AUTO-GENERATED by \`npm run sdk:generate\` from the OpenAPI spec served at
// /api/v1/openapi.json. DO NOT EDIT: CI regenerates this file and fails on drift.
`;

const JAVA_KEYWORDS = new Set([
  'abstract', 'continue', 'for', 'new', 'switch',
  'assert', 'default', 'goto', 'package', 'synchronized',
  'boolean', 'do', 'if', 'private', 'this',
  'break', 'double', 'implements', 'protected', 'throw',
  'byte', 'else', 'import', 'public', 'throws',
  'case', 'enum', 'instanceof', 'return', 'transient',
  'catch', 'extends', 'int', 'short', 'try',
  'char', 'final', 'interface', 'static', 'void',
  'class', 'finally', 'long', 'strictfp', 'volatile',
  'const', 'float', 'native', 'super', 'while',
  'record', 'var', 'yield', 'sealed', 'permits'
]);

export function escapeJavaIdent(name: string): string {
  const cleaned = name.replace(/[^A-Za-z0-9_]/g, '_');
  const valid = /^[0-9]/.test(cleaned) ? `m_${cleaned}` : cleaned;
  return JAVA_KEYWORDS.has(valid) ? `${valid}_` : valid;
}

export function escapeJavaString(str: string): string {
  return JSON.stringify(str);
}

function javaType(schema: JsonSchema | null | undefined, known: Set<string>, depth = 0): string {
  if (!schema || depth > 5) return 'Object';
  if (typeof schema.$ref === 'string') {
    const m = /^#\/components\/schemas\/(.+)$/.exec(schema.$ref);
    return m && known.has(m[1]) ? modelName(m[1]) : 'Object';
  }
  if (schema.oneOf || schema.anyOf) {
    return 'Object';
  }
  if (schema.allOf) {
    return schema.allOf.length === 1 ? javaType(schema.allOf[0], known, depth + 1) : 'Map<String, Object>';
  }
  const type = Array.isArray(schema.type) ? schema.type[0] : schema.type;
  switch (type) {
    case 'string':
      return 'String';
    case 'integer':
      return 'Long';
    case 'number':
      return 'Double';
    case 'boolean':
      return 'Boolean';
    case 'array':
      return `List<${javaType(schema.items, known, depth + 1)}>`;
    case 'object':
      return 'Map<String, Object>';
    default:
      return 'Object';
  }
}

export function emitJavaModels(doc: OpenApiDocument): string {
  const schemas = doc.components?.schemas ?? {};
  const known = new Set(Object.keys(schemas));
  const recordBlocks: string[] = [];

  for (const rawName of Object.keys(schemas).sort()) {
    const name = modelName(rawName);
    const s = schemas[rawName];

    if (s.properties && Object.keys(s.properties).length > 0) {
      const propKeys = Object.keys(s.properties).sort();
      const fields = propKeys.map((k) => {
        const fieldType = javaType(s.properties![k], known);
        const safeIdent = escapeJavaIdent(k);
        return `        @JsonProperty("${k}") ${fieldType} ${safeIdent}`;
      });

      recordBlocks.push(
        `    @JsonIgnoreProperties(ignoreUnknown = true)\n` +
        `    public record ${name}(\n${fields.join(',\n')}\n    ) {}`
      );
    } else {
      recordBlocks.push(
        `    @JsonIgnoreProperties(ignoreUnknown = true)\n` +
        `    public record ${name}(\n        @JsonProperty("value") Object value\n    ) {}`
      );
    }
  }

  return `${HEADER}package io.soroban.explorer.models;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;
import java.util.List;
import java.util.Map;

/**
 * Strongly typed DTO models corresponding to OpenAPI schemas.
 */
public final class Models {
    private Models() {}

${recordBlocks.join('\n\n')}
}
`;
}

export function emitJavaOperations(doc: OpenApiDocument, ops: NormalizedOperation[], fingerprint: string): string {
  const opEntries = ops.map((op) => {
    const pathParams = op.params.filter((p) => p.in === 'path').map((p) => escapeJavaString(p.name));
    const queryParams = op.params
      .filter((p) => p.in === 'query')
      .map((p) => {
        const req = p.required ? 'true' : 'false';
        const type = escapeJavaString(p.type ?? 'string');
        return `            new QueryParam(${escapeJavaString(p.name)}, ${type}, ${req})`;
      });

    const isPagination = op.params.some(
      (p) => p.name === 'cursor' || p.name === 'page' || p.name === 'offset' || p.name === 'limit'
    );

    return `        map.put(${escapeJavaString(op.id)}, new OperationDef(
            ${escapeJavaString(op.id)},
            ${escapeJavaString(op.method.toUpperCase())},
            ${escapeJavaString(op.path)},
            List.of(${pathParams.join(', ')}),
            List.of(\n${queryParams.join(',\n')}\n            ),
            ${op.body ? 'true' : 'false'},
            ${op.body?.required ? 'true' : 'false'},
            ${escapeJavaString(op.body?.contentType ?? '')},
            ${op.deprecated ? 'true' : 'false'},
            ${escapeJavaString(op.summary ?? '')},
            ${isPagination ? 'true' : 'false'}
        ));`;
  });

  return `${HEADER}package io.soroban.explorer;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Runtime metadata for every operation in the Soroban Explorer OpenAPI spec.
 */
public final class Operations {
    public static final String SPEC_VERSION = ${escapeJavaString(doc.info?.version ?? '0.0.0')};
    public static final String SPEC_FINGERPRINT = ${escapeJavaString(fingerprint)};
    public static final int OPERATION_COUNT = ${ops.length};

    public record QueryParam(
        String name,
        String type,
        boolean required
    ) {}

    public record OperationDef(
        String id,
        String method,
        String path,
        List<String> pathParams,
        List<QueryParam> queryParams,
        boolean hasBody,
        boolean bodyRequired,
        String contentType,
        boolean deprecated,
        String summary,
        boolean supportsPagination
    ) {}

    public static final Map<String, OperationDef> ALL;

    static {
        Map<String, OperationDef> map = new HashMap<>();
${opEntries.join('\n')}
        ALL = Collections.unmodifiableMap(map);
    }

    private Operations() {}
}
`;
}

export const javaEmitter: Emitter = ({ doc, ops, fingerprint }) => {
  return [
    {
      path: 'packages/java-client/src/main/java/io/soroban/explorer/Operations.java',
      content: emitJavaOperations(doc, ops, fingerprint),
    },
    {
      path: 'packages/java-client/src/main/java/io/soroban/explorer/models/Models.java',
      content: emitJavaModels(doc),
    },
  ];
};
